  if (cena == 1) {
    cena = 3
    basic.showString("CAMINHO ESCURO. A=VOLTAR B=SEGUIR")
  }
  else if (cena == 2) {
    cena = 1
    basic.showString("VOCE SAIU DA SALA")
  }
  else if (cena == 3) {
    cena = 5
    basic.showString("VOCE SE PERDEU. FIM")
  }
})
